8	export type { SpanAttrs, SpanKind } from "./attributes.ts";
9	
10	/** What the SDK hands a span body. `traceId` is the OpenTelemetry trace id, when the span has one. */
11	export interface ObsSpan {
12	  setAttribute(key: string, value: string | number | boolean): void;
13	  traceId?: string;
14	}
15	
16	/** The neatlogs SDK as its own type definitions declare it (`neatlogs` and `neatlogs/openai`). */
17	type NeatlogsModule = typeof import("neatlogs");
18	type WrapOpenAI = typeof import("neatlogs/openai").wrapOpenAI;
19	/** The OpenTelemetry span that trace()'s body receives. `neatlogs` also exports a `Span` decorator, so derive it. */
20	type NeatlogsSpan = Parameters<NeatlogsModule["trace"]>[1] extends (span: infer S) => unknown ? S : never;
21	
22	const NOOP_SPAN: ObsSpan = { setAttribute() {} };
