24	let sdk: NeatlogsModule | null = null;
25	let wrapOpenAI: WrapOpenAI | null = null;
26	let sessionId: string | undefined;
27	let warned = false;
28	let initPromise: Promise<boolean> | null = null;
29	let pendingSpans = 0;
30	let sentSpans = 0;
31	let failedSpans = 0;
32	/** Trace ids of the WORKFLOW roots opened since the last flush, printed when it ends. */
33	let rootTraces: string[] = [];
34	
35	/** Test hook: runs on `mod` as if initObs had started it (bun's mock.module cannot swap an SDK another file already loaded). */
36	export function _useSdkForTests(mod: unknown): void {
37	  sdk = mod as NeatlogsModule;
38	  initPromise = Promise.resolve(true);
39	}
