41	/** Test hook: forgets the running SDK so a test can start from a clean process state. */
42	export function _resetObsForTests(): void {
43	  sdk = null;
44	  wrapOpenAI = null;
45	  sessionId = undefined;
46	  warned = false;
47	  initPromise = null;
48	  pendingSpans = sentSpans = failedSpans = 0;
