53	  if (warned) return;
54	  warned = true;
55	  console.warn(`[roster] observability disabled: ${msg}`);
56	}
57	
58	/**
59	 * Starts neatlogs for this process. Resolves to true when tracing is live.
60	 * With NEATLOGS_API_KEY unset (or the SDK not installed) it resolves to false and warns once.
61	 */
62	export function initObs(opts: { workflowName: string }): Promise<boolean> {
63	  // One SDK init per process: later calls (any workflow name) reuse it; callers open their own root span.
64	  if (!initPromise) {
65	    const attempt = startSdk(opts);
66	    initPromise = attempt;
67	    // A failed start is not cached: a key set later may still start tracing.
68	    void attempt.then((ok) => {
69	      if (!ok && initPromise === attempt) initPromise = null;
70	    });
71	  }
72	  return initPromise;
73	}
74	
75	async function startSdk(opts: { workflowName: string }): Promise<boolean> {
76	  const apiKey = process.env.NEATLOGS_API_KEY;
77	  if (!apiKey) {
78	    warnOnce("NEATLOGS_API_KEY is not set");
79	    return false;
80	  }
81	  try {
82	    const mod = await import("neatlogs");
83	    await mod.init({ apiKey, workflowName: opts.workflowName });
84	    wrapOpenAI = (await import("neatlogs/openai")).wrapOpenAI;
85	    sdk = mod;
86	    return true;
87	  } catch (err) {
88	    warnOnce(`could not start neatlogs (${err instanceof Error ? err.message : String(err)})`);
89	    return false;
90	  }
91	}
92	
93	/**
94	 * Wraps an OpenAI-compatible client so each of its calls becomes an LLM span. Returns the client unchanged
95	 * while tracing is off, so callers may wrap at call time (the CLI builds clients before initObs runs).
96	 */
97	export function traceOpenAI<T extends object>(client: T): T {
98	  return sdk && wrapOpenAI ? wrapOpenAI(client) : client;
99	}
100	
101	/** True once initObs has enabled tracing. */
102	export function obsEnabled(): boolean {
103	  return sdk !== null;
104	}
105	
106	/** Tags the current review. Every span opened after this carries it as `session.id`. */
107	export function setSession(reviewId: string): void {
108	  sessionId = reviewId;
109	}
110	
111	/**
112	 * Runs `fn` inside one span of the given kind. The span is nested under whatever span is active,
113	 * so calling withSpan inside a WORKFLOW body builds the tree. Errors propagate after the span closes.
114	 */
115	export async function withSpan<T>(
116	  kind: SpanKind,
117	  name: string,
118	  attrs: SpanAttrs,
119	  fn: (span: ObsSpan) => Promise<T>,
120	): Promise<T> {
121	  if (!sdk) return fn(NOOP_SPAN);
122	  const client = sdk;
123	  // The SDK groups a review's traces by session on the WORKFLOW root; every span also carries it as an attribute.
124	  const options: TraceOptions = { name, kind };
125	  if (kind === "WORKFLOW" && sessionId !== undefined) options.sessionId = sessionId;
126	  pendingSpans += 1;
127	  return client.trace(options, async (span) => {
128	    for (const [key, value] of Object.entries(toAttributes(attrs))) span.setAttribute(key, value);
129	    if (sessionId !== undefined) span.setAttribute("session.id", sessionId);
130	    const obsSpan = toObsSpan(span);
131	    if (kind === "WORKFLOW" && obsSpan.traceId && !rootTraces.includes(obsSpan.traceId)) rootTraces.push(obsSpan.traceId);
132	    return fn(obsSpan);
133	  });
134	}
135	
136	/** Adapts an SDK span (an OpenTelemetry span) to ObsSpan. The trace id comes from spanContext(). */
137	function toObsSpan(span: NeatlogsSpan): ObsSpan {
138	  // A bare `traceId` field is honored too, for span stand-ins that carry one directly.
139	  const direct = (span as { traceId?: string }).traceId;
140	  return {
141	    setAttribute: (key, value) => void span.setAttribute(key, capAttr(value)),
142	    traceId: direct ?? span.spanContext?.().traceId,
143	  };
144	}
145	
146	/** Outcome of one replay attempt, recorded as a finished TOOL span. */
147	export interface AttemptOutcome {
148	  failureCode?: FailureCode | FailureCode[];
149	  evidenceLevel?: EvidenceLevel;
150	  costUsd?: number;
151	}
152	
153	/** Records one replay attempt as a TOOL span carrying its outcome. The span has no body work of its own. */
154	export async function recordAttempt(spanAttrs: SpanAttrs, attempt: number, outcome: AttemptOutcome): Promise<void> {
155	  await withSpan("TOOL", `replay attempt ${attempt}`, { ...spanAttrs, ...outcome, attempt }, async () => undefined);
156	}
157	
158	/** How long the SDK may take to export on one flush attempt (flushAllDetailed's timeout). */
159	export const FLUSH_TIMEOUT_MS = 60_000;
160	/** Extra wait on top of the SDK's own timeout, so the SDK reports its outcome before ours fires. */
161	export const FLUSH_GRACE_MS = 5_000;
162	
163	export interface FlushOptions {
164	  /** Per attempt. Default FLUSH_TIMEOUT_MS. */
165	  timeoutMs?: number;
166	  /** Extra attempts after the first. Default 1. */
167	  retries?: number;
168	  /** Where the one failure line goes. Default console.warn. */
169	  log?: (msg: string) => void;
170	  /** Where flushObs's export report and trace ids go. Default console.log. */
171	  print?: (msg: string) => void;
172	}
173	
174	/** What flushAllDetailed resolves to (neatlogs FlushAllResult). */
175	interface DetailedFlush {
176	  success: boolean;
177	  outcomes: Array<{ pipeline: string; success: boolean; timedOut: boolean; error?: string }>;
178	}
179	
180	const isDetailed = (r: unknown): r is DetailedFlush =>
181	  typeof r === "object" && r !== null && typeof (r as DetailedFlush).success === "boolean" && Array.isArray((r as DetailedFlush).outcomes);
182	
183	/** Why a detailed flush failed, from the SDK's per-pipeline outcomes. */
184	function detailedReason(r: DetailedFlush): string {
185	  const bad = r.outcomes.filter((o) => !o.success);
186	  if (bad.length === 0) return "the SDK reported a failed export";
187	  return bad.map((o) => `${o.pipeline}: ${o.timedOut ? "timed out" : (o.error ?? "failed")}`).join("; ");
188	}
189	
190	/**
191	 * Runs `flush` until it succeeds, each attempt bounded by a timeout. A throw, a timeout or a `false` result is a
192	 * failed attempt. When every attempt fails it logs one line and resolves to false; it never throws.
193	 */
194	export function flushWithRetry(flush: () => Promise<unknown>, opts: FlushOptions = {}): Promise<boolean> {
195	  return flushCounted(flush, opts, 0);
196	}
197	
198	async function flushCounted(flush: () => Promise<unknown>, opts: FlushOptions, batch: number): Promise<boolean> {
199	  const timeoutMs = opts.timeoutMs ?? FLUSH_TIMEOUT_MS;
200	  const attempts = 1 + (opts.retries ?? 1);
201	  let reason = "";
202	  for (let i = 0; i < attempts; i++) {
203	    let timer: ReturnType<typeof setTimeout> | undefined;
204	    const timeout = new Promise<"timeout">((res) => {
205	      timer = setTimeout(() => res("timeout"), timeoutMs);
206	    });
207	    try {
208	      const r = await Promise.race([Promise.resolve().then(flush), timeout]);
209	      if (r === "timeout") reason = `timed out after ${timeoutMs / 1000} s`;
210	      else if (r === false) reason = "the SDK reported a failed export";
211	      else if (isDetailed(r) && !r.success) reason = detailedReason(r);
212	      else {
213	        sentSpans += batch;
214	        pendingSpans -= batch;
215	        return true;
216	      }
217	    } catch (err) {
218	      reason = err instanceof Error ? err.message : String(err);
219	    } finally {
220	      clearTimeout(timer);
221	    }
222	  }
223	  failedSpans += batch;
224	  pendingSpans -= batch;
225	  (opts.log ?? console.warn)(
226	    `[roster] neatlogs flush failed after ${attempts} attempts (${reason}); ${sentSpans} spans sent, ${failedSpans} failed; traces may be incomplete`,
227	  );
228	  return false;
229	}
230	
231	/** Spans the SDK says it has lost so far (queue drops, failed exports, masked drops), or null when it cannot say. */
232	function sdkDrops(client: NeatlogsModule): number | null {
233	  if (typeof client.getDeliveryDiagnostics !== "function") return null;
234	  try {
235	    const d = client.getDeliveryDiagnostics();
236	    return d.spanQueueDrops + d.spanExportFailures + d.maskedSpanDrops;
237	  } catch {
238	    return null;
239	  }
240	}
241	
242	/**
243	 * Sends buffered spans. Call once before the process exits. A no-op when tracing is off.
244	 * Prints what the SDK exported and dropped, then the trace id of every WORKFLOW root opened since the last flush.
245	 * Never throws: a failed flush logs one line, so it cannot change the exit code.
246	 */
247	export async function flushObs(opts: FlushOptions = {}): Promise<boolean> {
248	  if (!sdk) return true;
249	  const client = sdk;
250	  const timeoutMs = opts.timeoutMs ?? FLUSH_TIMEOUT_MS;
251	  const print = opts.print ?? ((m: string) => console.log(m));
252	  const batch = pendingSpans;
253	  const traces = rootTraces;
254	  rootTraces = [];
255	  const dropsBefore = sdkDrops(client);
256	  // flushAllDetailed takes the SDK timeout and names the pipeline that failed; SDK builds (and test stand-ins)
257	  // without it fall back to flushAll, then flush(). Our own timeout waits a little longer so the SDK answers first.
258	  // The SDK reports no per-span result, so "exported" is the spans opened since the last flush, less the SDK's drops.
259	  const ok = await flushCounted(
260	    () =>
261	      typeof client.flushAllDetailed === "function"
262	        ? client.flushAllDetailed(timeoutMs)
263	        : typeof client.flushAll === "function"
264	          ? client.flushAll(timeoutMs)
265	          : client.flush(),
266	    { ...opts, timeoutMs: timeoutMs + FLUSH_GRACE_MS },
267	    batch,
268	  );
269	  const dropsAfter = sdkDrops(client);
270	  const dropped = dropsBefore !== null && dropsAfter !== null ? Math.max(0, dropsAfter - dropsBefore) : null;
271	  const exported = ok ? Math.max(0, batch - (dropped ?? 0)) : 0;
272	  print(`[roster] neatlogs: ${exported} spans exported, ${dropped ?? "unknown"} dropped${ok ? "" : " (flush failed)"}`);
273	  for (const id of traces) print(`[roster] neatlogs trace ${id}`);
274	  return ok;
275	}
