Design the code carefully with strict TS.

```ts
// Focused failure context for one trace (DESIGN.md §"Observability (neatlogs)").
// The coordinator gets a handful of counts and names instead of a raw span tree.

export type SpanNode = {
  name: string;
  kind: string;
  status: "ok" | "error";
  attributes: Record<string, unknown>;
  durationMs: number;
  children: SpanNode[];
};

/** One failed span: its name, and the message from attributes["error.message"] when it carries one. */
export interface SpanError {
  name: string;
  message?: string;
}

export interface TraceSummary {
  toolCalls: number;
  errors: SpanError[];
  retries: number;
  costUsd: number | null;
  slowest: { name: string; durationMs: number } | null;
  oneLine: string;
}

const ERROR_MESSAGE = "error.message";
const ATTEMPT = "roster.attempt";
const COST = "roster.cost_usd";
const TOOL = "TOOL";

/** Pre-order walk: parents before children, siblings left to right — the order the spans were opened. */
function walk(node: SpanNode, visit: (n: SpanNode) => void): void {
  visit(node);
  for (const child of node.children) walk(child, visit);
}

/** The message a span carries for its failure, when it carries one. */
function errorMessage(node: SpanNode): string | undefined {
  const v = node.attributes[ERROR_MESSAGE];
  if (typeof v === "string") return v;
  if (typeof v === "number") return String(v);
  return undefined;
}

/** Attempt number from roster.attempt, when the span has a numeric one. */
function attempt(node: SpanNode): number | null {
  const v = node.attributes[ATTEMPT];
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}

/** Cost in USD from roster.cost_usd, when the span has a numeric one. */
function cost(node: SpanNode): number | null {
  const v = node.attributes[COST];
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}

function plural(n: number, one: string, many = `${one}s`): string {
  return `${n} ${n === 1 ? one : many}`;
}
```

