```ts
export function summariseTrace(root: SpanNode): TraceSummary {
  let toolCalls = 0;
  const errors: SpanError[] = [];
  let retries = 0;
  let costUsd: number | null = null;
  let slowest: { name: string; durationMs: number } | null = null;

  walk(root, (span) => {
    if (span.kind === TOOL) {
      toolCalls += 1;
      if (slowest === null || span.durationMs > slowest.durationMs) {
        slowest = { name: span.name, durationMs: span.durationMs };
      }
    }
    if (span.status === "error") {
      const message = errorMessage(span);
      errors.push(message === undefined ? { name: span.name } : { name: span.name, message });
    }
    const a = attempt(span);
    if (a !== null && a > 1) retries += 1;
    const c = cost(span);
    if (c !== null) costUsd = (costUsd ?? 0) + c;
  });

  return { toolCalls, errors, retries, costUsd, slowest, oneLine: oneLine({...}) };
