// Focused failure context for one review's trace (DESIGN.md §"Observability (neatlogs)").
// The coordinator gets counts, error names and one line instead of the raw span tree.

/** One span of a trace, as the tree a review's spans form: WORKFLOW root → AGENT → TOOL / GUARDRAIL. */
export type SpanNode = {
  name: string;
  kind: string;
  status: "ok" | "error";
  attributes: Record<string, unknown>;
  durationMs: number;
  children: SpanNode[];
};

/** A span that failed: its name, plus the message its `error.message` attribute carries when it has one. */
export interface SpanError {
  name: string;
  message?: string;
}

export interface TraceSummary {
  toolCalls: number;
  errors: SpanError[];
  retries: number;
  costUsd: number | null;
  slowest: { name: string; durationMs: number } | null;
  oneLine: string;
}

/** The kind a tool call is recorded with (src/obs/attributes.ts SpanKind). Matched exactly, as span kinds are. */
const TOOL = "TOOL";
const ERROR_MESSAGE = "error.message";
const ATTEMPT = "roster.attempt";
const COST = "roster.cost_usd";

/**
 * Visits `node` and everything under it, parents before children and siblings left to right:
 * the order the spans were opened in. A tree that loops back on itself (not a SpanNode, but
 * a hand-built one could) is walked once rather than forever.
 */
function walk(node: SpanNode, visit: (span: SpanNode) => void, onPath: Set<SpanNode> = new Set()): void {
  if (onPath.has(node)) return;
  visit(node);
  onPath.add(node);
  for (const child of node.children) walk(child, visit, onPath);
  onPath.delete(node);
}

const asNumber = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);

/** The failure message a span carries. Numbers are stringified; anything else means "no message". */
function errorMessage(span: SpanNode): string | undefined {
  const raw = span.attributes[ERROR_MESSAGE];
  if (typeof raw === "string") return raw;
  if (typeof raw === "number") return String(raw);
  return undefined;
}

const plural = (n: number, one: string, many = `${one}s`): string => `${n} ${n === 1 ? one : many}`;

/**
 * The one-line summary. Tool calls always lead it; a segment with nothing to report is left out,
 * so a clean run reads `3 tool calls, $0.04` and never `0 errors, 0 retries`.
 */
function oneLine(s: Omit<TraceSummary, "oneLine">): string {
  const parts = [plural(s.toolCalls, "tool call")];
  if (s.errors.length > 0) {
    // The parenthetical names the failing spans in the order they appear, once each: repeats add nothing.
    const names = [...new Set(s.errors.map((e) => e.name))];
    parts.push(`${plural(s.errors.length, "error")} (${names.join(", ")})`);
  }
  if (s.retries > 0) parts.push(plural(s.retries, "retry", "retries"));
  if (s.costUsd !== null) parts.push(`$${s.costUsd.toFixed(2)}`);
  return parts.join(", ");
}

/**
 * Summarises one trace: how many tool calls it made, which spans failed and why, how many attempts
 * were retries, what it cost, and the slowest tool call. Pure: the tree is only read.
 */
export function summariseTrace(root: SpanNode): TraceSummary {
  let toolCalls = 0;
  let slowest: { name: string; durationMs: number } | null = null;
  const errors: SpanError[] = [];
  let retries = 0;
  let costUsd: number | null = null;

  walk(root, (span) => {
    if (span.kind === TOOL) {
      toolCalls += 1;
      // A span with no usable duration counts as 0, so it never hides a real tool call from `slowest`.
      const durationMs = asNumber(span.durationMs) ?? 0;
      if (slowest === null || durationMs > slowest.durationMs) slowest = { name: span.name, durationMs };
    }
    if (span.status === "error") {
      const message = errorMessage(span);
      errors.push(message === undefined ? { name: span.name } : { name: span.name, message });
    }
    const attempt = asNumber(span.attributes[ATTEMPT]);
    if (attempt !== null && attempt > 1) retries += 1;
    const cost = asNumber(span.attributes[COST]);
    if (cost !== null) costUsd = (costUsd ?? 0) + cost;
  });

