input.content:
// F05: summariseTrace turns one review's span tree into counts, error names and a one-line summary,
// so the coordinator reads failure context instead of a raw trace. Trees here have the shape a review
// really builds (WORKFLOW `review` → AGENT `coordinator` → TOOL steps, plus GUARDRAIL `gate`; src/obs/index.ts),
// and the roster.* attribute keys come from src/obs/attributes.ts rather than being retyped.
import { describe, expect, test } from "bun:test";
import { ATTR } from "../src/obs/attributes.ts";
import { summariseTrace, type SpanNode } from "../src/obs/summary.ts";

/** A TOOL span, as the design's trace structure uses them. */
function tool(name: string, over: Partial<SpanNode> = {}): SpanNode {
  return { name, kind: "TOOL", status: "ok", attributes: {}, durationMs: 10, children: [], ...over };
}

/** The WORKFLOW root of one review. */
function trace(children: SpanNode[] = []): SpanNode {
  return { name: "review", kind: "WORKFLOW", status: "ok", attributes: {}, durationMs: 0, children };
}

/** The AGENT span the coordinator's steps hang under. */
function coordinator(children: SpanNode[]): SpanNode {
  return { name: "coordinator", kind: "AGENT", status: "ok", attributes: {}, durationMs: 0, children };
}

describe("summariseTrace counts and names", () => {
  test("counts TOOL spans at any depth", () => {
    const root = trace([
      tool("ingest"),
      coordinator([tool("score"), coordinator([tool("replay attempt 1")])]),
      { name: "grade", kind: "LLM", status: "ok", attributes: {}, durationMs: 30, children: [] },
    ]);

    expect(summariseTrace(root).toolCalls).toBe(4);
  });

  test("counts no other kind as a tool call, whatever its status", () => {
    // Kinds are the SpanKind union's uppercase names; `tool` is not one of them.
    const root = trace([
      { name: "tool", kind: "tool", status: "ok", attributes: {}, durationMs: 5, children: [] },
      { name: "gate", kind: "GUARDRAIL", status: "error", attributes: {}, durationMs: 5, children: [] },
    ]);

    expect(summariseTrace(root).toolCalls).toBe(0);
  });

  test("lists failed spans in trace order, with the message each carries", () => {
    const root = trace([
      tool("install", { status: "error", attributes: { "error.message": "exit code 1" } }),
      tool("fine"),
      coordinator([
        { name: "gate", kind: "GUARDRAIL", status: "error", attributes: { "error.message": "scope guard failed" } },
      ]),
    ]);

    // A failed span of any kind is an error, not just a failed tool call.
    expect(summariseTrace(root).errors).toEqual([
      { name: "install", message: "exit code 1" },
      { name: "gate", message: "scope guard failed" },
    ]);
  });

  test("omits the message when the span carries none", () => {
    const missing = trace([tool("install", { status: "error" })]);
    expect(summariseTrace(missing).errors).toEqual([{ name: "install" }]);
    expect(summariseTrace(missing).errors[0].message).toBeUndefined();

    // Only `error.message` is the message; a differently named attribute is not.
    const other = trace([tool("install", { status: "error", attributes: { message: "nope", error: "nope" } })]);
    expect(summariseTrace(other).errors).toEqual([{ name: "install" }]);
  });

  test("counts a span as a retry only when its attempt is above the first", () => {
    const root = trace([
      tool("replay attempt 1", { attributes: { [ATTR.attempt]: 1 } }),
      tool("replay attempt 2", { attributes: { [ATTR.attempt]: 2 } }),
      coordinator([tool("replay attempt 3", { attributes: { [ATTR.attempt]: 3 } })]),
      tool("no attempt"),
    ]);

    expect(summariseTrace(root).retries).toBe(2);
  });

  test("ignores attempts that are not numbers above one", () => {
    const root = trace([
      tool("a", { attributes: { [ATTR.attempt]: "2" } }),
      tool("b", { attributes: { [ATTR.attempt]: Number.NaN } }),
      tool("c", { attributes: { [ATTR.attempt]: null } }),
    ]);

    expect(summariseTrace(root).retries).toBe(0);
  });

  test("sums roster.cost_usd across the tree", () => {
    const root = trace([
      tool("a", { attributes: { [ATTR.costUsd]: 1.25 } }),
      coordinator([tool("b", { attributes: { [ATTR.costUsd]: 0.75 } })]),
      { name: "coordinator", kind: "AGENT", status: "ok", attributes: { [ATTR.costUsd]: 0.5 }, durationMs: 0, children: [] },
    ]);

    expect(summariseTrace(root).costUsd).toBe(2.5);
  });

  test("returns null cost when no span is priced, and 0 when the cost is known to be zero", () => {
    expect(summariseTrace(trace([tool("a"), tool("b")])).costUsd).toBeNull();
    // An unpriced span is not a zero: only a real 0 makes the total 0.
    expect(summariseTrace(trace([tool("a", { attributes: { [ATTR.costUsd]: 0 } })])).costUsd).toBe(0);
    expect(summariseTrace(trace([tool("a", { attributes: { [ATTR.costUsd]: "0.21" } })])).costUsd).toBeNull();
  });

  test("picks the longest tool call, ignoring a longer span of another kind", () => {
    const root = trace([
      tool("fast", { durationMs: 10 }),
      { name: "score", kind: "AGENT", status: "ok", attributes: {}, durationMs: 1_000, children: [] },
      coordinator([tool("slow", { durationMs: 50 })]),
    ]);

    expect(summariseTrace(root).slowest).toEqual({ name: "slow", durationMs: 50 });
  });

  test("keeps the first of two equally long tool calls, and a failed one still counts", () => {
    const first = trace([tool("first", { durationMs: 50 }), tool("second", { durationMs: 50 })]);
    expect(summariseTrace(first).slowest).toEqual({ name: "first", durationMs: 50 });

    const failed = trace([tool("install", { status: "error", durationMs: 500 })]);
    expect(summariseTrace(failed).slowest).toEqual({ name: "install", durationMs: 500 });
  });

  test("has no slowest tool call when the trace has none", () => {
    const root = trace([{ name: "coordinator", kind: "AGENT", status: "ok", attributes: {}, durationMs: 30, children: [] }]);

    expect(summariseTrace(root).slowest).toBeNull();
  });
});

describe("summariseTrace one-line summary", () => {
  test("reads like the design's example", () => {
    // 12 clean tool calls plus the two that failed: the counterexample the design writes out.
    const root = trace([
      tool("install", {
        status: "error",
        attributes: { "error.message": "exit code 1", [ATTR.attempt]: 2, [ATTR.costUsd]: 0.21 },
        durationMs: 500,
      }),
      tool("test", { status: "error", attributes: { "error.message": "2 tests failed" }, durationMs: 90 }),
      ...Array.from({ length: 12 }, (_, i) => tool(`step-${i + 1}`, { durationMs: 5 + i })),
    ]);

    const summary = summariseTrace(root);
    expect(summary.toolCalls).toBe(14);
    expect(summary.errors.map((e) => e.name)).toEqual(["install", "test"]);
    expect(summary.retries).toBe(1);
    expect(summary.costUsd).toBe(0.21);
    expect(summary.oneLine).toBe("14 tool calls, 2 errors (install, test), 1 retry, $0.21");
  });

  test("leaves out a segment with nothing to report", () => {
    expect(summariseTrace(trace([tool("ingest"), tool("score")])).oneLine).toBe("2 tool calls");
    expect(summariseTrace(trace()).oneLine).toBe("0 tool calls");
    // Unknown cost says nothing about cost: null is not $0.00.
    expect(summariseTrace(trace([tool("a", { attributes: { [ATTR.costUsd]: 0 } })])).oneLine).toBe("1 tool call, $0.00");
  });

  test("uses singulars and cents", () => {
    const root = trace([
      tool("test", { status: "error", attributes: { [ATTR.attempt]: 2, [ATTR.costUsd]: 2 } }),
    ]);

    expect(summariseTrace(root).oneLine).toBe("1 tool call, 1 error (test), 1 retry, $2.00");
  });

  test("names a repeatedly failing span once, and counts each failure", () => {
    const root = trace([
      tool("test", { status: "error" }),
      tool("install", { status: "error" }),
      tool("test", { status: "error" }),
    ]);

    expect(summariseTrace(root).oneLine).toBe("3 tool calls, 3 errors (test, install)");
  });

  test("handles a deeply nested trace", () => {
    const root = trace([
      coordinator([
        coordinator([coordinator([coordinator([tool("deep", { status: "error", attributes: { "error.message": "boom" } })])])]),
      ]),
    ]);

    expect(summariseTrace(root).oneLine).toBe("1 tool call, 1 error (deep)");
  });
});

describe("summariseTrace reads the trace and nothing else", () => {
  test("does not change the tree it is given, and is repeatable", () => {
    const root = trace([
      tool("install", { status: "error", attributes: { "error.message": "boom", [ATTR.costUsd]: 0.21 } }),
    ]);
    const before = structuredClone(root);

    const once = summariseTrace(root);
    expect(root).toEqual(before);
    expect(summariseTrace(root)).toEqual(once);
  });

  test("terminates on a tree that loops back on itself", () => {
    // Not a SpanNode by construction, but a hand-built one must not hang the coordinator.
    const loop = tool("loop");
    loop.children = [loop, tool("after")];

    const summary = summariseTrace(loop);
    expect(summary.toolCalls).toBe(2);
    expect(summary.slowest).toEqual({ name: "loop", durationMs: 10 });
  });
});

